package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Execute the ping command with the specified count
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
	}

	// Parse the output to extract latency values
	outputStr := string(output)
	latencies, err := parseLatencies(outputStr)
	if err != nil {
		return 0, fmt.Errorf("failed to parse latencies: %v", err)
	}

	if len(latencies) == 0 {
		return 0, fmt.Errorf("no latency values found in ping output")
	}

	// Calculate the average latency
	var sum float64
	for _, lat := range latencies {
		sum += lat
	}
	average := sum / float64(len(latencies))

	return average, nil
}

// parseLatencies extracts individual latency values from the ping command output.
func parseLatencies(output string) ([]float64, error) {
	var latencies []float64

	// Regular expression to match time=XX.X ms
	re := regexp.MustCompile(`time=([0-9]+\.?[0-9]*) ms`)
	matches := re.FindAllStringSubmatch(output, -1)

	for _, match := range matches {
		if len(match) >= 2 {
			latency, err := strconv.ParseFloat(match[1], 64)
			if err != nil {
				continue
			}
			latencies = append(latencies, latency)
		}
	}

	// If the above regex didn't find matches, try alternative format (e.g., time<1ms)
	if len(latencies) == 0 {
		reAlt := regexp.MustCompile(`time<([0-9]+\.?[0-9]*) ms`)
		matchesAlt := reAlt.FindAllStringSubmatch(output, -1)
		for _, match := range matchesAlt {
			if len(match) >= 2 {
				latency, err := strconv.ParseFloat(match[1], 64)
				if err != nil {
					continue
				}
				latencies = append(latencies, latency)
			}
		}
	}

	// Try parsing summary statistics if individual times aren't available
	if len(latencies) == 0 {
		// Look for avg/min/max/mdev line
		reSummary := regexp.MustCompile(`(?:rtt|round-trip)\s+\S+\s*=\s*([0-9]+\.?[0-9]*)/([0-9]+\.?[0-9]*)/([0-9]+\.?[0-9]*)/([0-9]+\.?[0-9]*)`)
		summaryMatch := reSummary.FindStringSubmatch(output)
		if len(summaryMatch) >= 3 {
			// The second capture group is typically the average
			avg, err := strconv.ParseFloat(summaryMatch[2], 64)
			if err == nil {
