package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds. It uses the system's ping command.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Determine the appropriate ping command flags based on the OS.
	// -c for Linux/macOS, -n for Windows.
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w\nOutput: %s", err, string(output))
	}

	return parsePingOutput(string(output), host)
}

// parsePingOutput extracts the average latency from the ping command output.
// It supports both Linux/macOS and Windows ping output formats.
func parsePingOutput(output, host string) (float64, error) {
	lines := strings.Split(output, "\n")

	// Try Linux/macOS format: rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms
	for _, line := range lines {
		if strings.Contains(line, "rtt min/avg/max/mdev") || strings.Contains(line, "round-trip min/avg/max") {
			re := regexp.MustCompile(`=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
			matches := re.FindStringSubmatch(line)
			if len(matches) >= 2 {
				avg, err := strconv.ParseFloat(matches[1], 64)
				if err != nil {
					return 0, fmt.Errorf("failed to parse average latency: %w", err)
				}
				return avg, nil
			}
		}
	}

	// Try Windows format: Minimum = 1ms, Maximum = 3ms, Average = 2ms
	for _, line := range lines {
		if strings.Contains(line, "Average") && strings.Contains(line, "ms") {
			re := regexp.MustCompile(`Average\s*=\s*(\d+)ms`)
			matches := re.FindStringSubmatch(line)
			if len(matches) >= 2 {
				avg, err := strconv.ParseFloat(matches[1], 64)
				if err != nil {
					return 0, fmt.Errorf("failed to parse average latency: %w", err)
				}
				return avg, nil
			}
		}
	}

	return 0, fmt.Errorf("could not parse average latency from ping output for host %s", host)
}

func main() {
	// Example usage
	host := "google.com"
	count := 4

	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avgLatency)
}

