package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds. It uses the system's ping command.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Build the ping command. The flags -c (count) and -i (interval) are
	// widely supported on Unix-like systems. On Windows, the flag is -n.
	// This implementation assumes a Unix-like environment (Linux/macOS).
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)

	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w\nOutput: %s", err, string(output))
	}

	return parsePingOutput(string(output), count)
}

// parsePingOutput extracts the average round-trip time from ping output.
// It looks for the summary line like: "rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms"
func parsePingOutput(output string, expectedCount int) (float64, error) {
	// Check for packet loss
	lossRegex := regexp.MustCompile(`(\d+)% packet loss`)
	lossMatch := lossRegex.FindStringSubmatch(output)
	if lossMatch != nil {
		lossPercent, _ := strconv.ParseFloat(lossMatch[1], 64)
		if lossPercent == 100.0 {
			return 0, fmt.Errorf("100%% packet loss, host unreachable")
		}
	}

	// Extract average RTT from the summary line
	rttRegex := regexp.MustCompile(`rtt min/avg/max/mdev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`)
	rttMatch := rttRegex.FindStringSubmatch(output)
	if rttMatch != nil {
		avg, err := strconv.ParseFloat(rttMatch[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average RTT: %w", err)
		}
		return avg, nil
	}

	// Fallback: try to parse individual time values and compute average
	timeRegex := regexp.MustCompile(`time=([\d.]+) ms`)
	timeMatches := timeRegex.FindAllStringSubmatch(output, -1)
	if len(timeMatches) > 0 {
		var total float64
		for _, match := range timeMatches {
			t, err := strconv.ParseFloat(match[1], 64)
			if err != nil {
				continue
			}
			total += t
		}
		return total / float64(len(timeMatches)), nil
	}

	return 0, fmt.Errorf("could not parse ping output: %s", strings.TrimSpace(output))
}

func main() {
	// Example usage
	host := "google.com"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

