package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds. It uses the system's ping command.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0, got %d", count)
	}

	// Use -c for count (Linux/macOS) or -n (Windows)
	// Detect OS and set appropriate flags
	var cmd *exec.Cmd
	if isWindows() {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w\nOutput: %s", err, string(output))
	}

	return parsePingOutput(string(output), isWindows())
}

// isWindows checks if the current OS is Windows.
func isWindows() bool {
	cmd := exec.Command("cmd", "/c", "ver")
	err := cmd.Run()
	return err == nil
}

// parsePingOutput extracts the average round-trip time from ping output.
func parsePingOutput(output string, windows bool) (float64, error) {
	if windows {
		return parseWindowsPing(output)
	}
	return parseUnixPing(output)
}

// parseUnixPing parses ping output from Linux/macOS.
// Example line: rtt min/avg/max/mdev = 10.123/15.456/20.789/3.210 ms
func parseUnixPing(output string) (float64, error) {
	lines := strings.Split(output, "\n")
	for _, line := range lines {
		if strings.Contains(line, "rtt") && strings.Contains(line, "/") {
			re := regexp.MustCompile(`=\s*[\d.]+/([\d.]+)/`)
			matches := re.FindStringSubmatch(line)
			if len(matches) >= 2 {
				avg, err := strconv.ParseFloat(matches[1], 64)
				if err != nil {
					return 0, fmt.Errorf("failed to parse average latency: %w", err)
				}
				return avg, nil
			}
		}
	}
	return 0, fmt.Errorf("could not find average latency in ping output:\n%s", output)
}

// parseWindowsPing parses ping output from Windows.
// Example line: Minimum = 10ms, Maximum = 20ms, Average = 15ms
func parseWindowsPing(output string) (float64, error) {
	re := regexp.MustCompile(`Average\s*=\s*(\d+)ms`)
	matches := re.FindStringSubmatch(output)
	if len(matches) >= 2 {
		avg, err := strconv.ParseFloat(matches[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %w", err)
		}
		return avg, nil
	}

	// Alternative: try to parse from individual replies
	re = regexp.MustCompile(`time[=<]\s*(\d+)ms`)
	allMatches := re.FindAllStringSubmatch(output, -1)
	if len(allMatches) == 0 {
		return 0, fmt.Errorf("could not find latency information in ping output:\n%s", output)
	}

	var total float64
	for _, match := range allMatches {
		val, err := strconv.ParseFloat(match[1], 64)
		if err != nil {
			continue
		}
		total += val
	}
	if len(allMatches) > 0 {
		return total / float64(len(allMatches)), nil
	}

	return 0, fmt.Errorf("could not parse average latency from ping output:\n%s", output)
}

func main() {
	// Example usage
	avg, err := MeasureLatency("google.com", 4)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}
	fmt.Printf("Average latency: %.2f ms\n", avg)
}

