import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Execute the ping command with the specified count
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
	}

	outputStr := string(output)

	// Parse the summary line to extract average latency
	// Typical output format: "round-trip min/avg/max/stddev = 1.234/2.345/3.456/0.123 ms"
	// or "rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms"
	re := regexp.MustCompile(`(?:round-trip|rtt)\s+min/avg/max/(?:stddev|mdev)\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	matches := re.FindStringSubmatch(outputStr)
	if len(matches) < 2 {
		// Try alternative format for some ping implementations
		// e.g., "round-trip min/avg/max = 1.234/2.345/3.456 ms"
		re2 := regexp.MustCompile(`(?:round-trip|rtt)\s+min/avg/max\s*=\s*[\d.]+/([\d.]+)/[\d.]+\s*ms`)
		matches = re2.FindStringSubmatch(outputStr)
		if len(matches) < 2 {
			// Fallback: parse all time= values from individual ping lines
			timeRe := regexp.MustCompile(`time=([\d.]+)\s*ms`)
			timeMatches := timeRe.FindAllStringSubmatch(outputStr, -1)
			if len(timeMatches) == 0 {
				return 0, fmt.Errorf("could not parse latency from ping output: %s", outputStr)
			}

			var total float64
			for _, match := range timeMatches {
				t, err := strconv.ParseFloat(match[1], 64)
				if err != nil {
					return 0, fmt.Errorf("could not parse time value: %v", err)
				}
				total += t
			}
			return total / float64(len(timeMatches)), nil
		}
	}

	avg, err := strconv.ParseFloat(strings.TrimSpace(matches[1]), 64)
	if err != nil {
		return 0, fmt.Errorf("could not parse average latency: %v", err)
	}

	return avg, nil
}

func main() {
	// Example usage
	avg, err := MeasureLatency("google.com", 4)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Average latency: %.2f ms\n", avg)
}

