package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
// It uses the system's ping command via os/exec.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0, got %d", count)
	}

	// Determine the ping command flags based on the operating system.
	// Linux/macOS: ping -c <count> <host>
	// Windows: ping -n <count> <host>
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)

	// Run the command and capture combined output.
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
	}

	// Parse the output to extract round-trip times.
	times, err := parsePingOutput(string(output))
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %v", err)
	}

	if len(times) == 0 {
		return 0, fmt.Errorf("no ping responses received")
	}

	// Calculate the average latency.
	var sum float64
	for _, t := range times {
		sum += t
	}
	return sum / float64(len(times)), nil
}

// parsePingOutput extracts round-trip time values from the ping command output.
// It looks for patterns like "time=12.3 ms" in the output.
func parsePingOutput(output string) ([]float64, error) {
	// Regular expression to match "time=<value> ms" (case-insensitive for time).
	re := regexp.MustCompile(`[Tt]ime[=<]\s*([0-9]+\.?[0-9]*)\s*ms`)
	matches := re.FindAllStringSubmatch(output, -1)

	if matches == nil {
		return nil, fmt.Errorf("no time values found in ping output")
	}

	var times []float64
	for _, match := range matches {
		if len(match) < 2 {
			continue
		}
		val, err := strconv.ParseFloat(strings.TrimSpace(match[1]), 64)
		if err != nil {
			continue
		}
		times = append(times, val)
	}

	return times, nil
}

func main() {
	// Example usage
	latency, err := MeasureLatency("google.com", 4)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}
	fmt.Printf("Average latency to google.com: %.2f ms\n", latency)
}

