package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0, got %d", count)
	}

	// Execute the ping command with -c for count and -q for quiet output
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), "-q", host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w\nOutput: %s", err, string(output))
	}

	// Parse the output to extract average latency
	// The ping -q summary line looks like:
	// rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms
	outputStr := string(output)

	// Try to match the rtt line
	re := regexp.MustCompile(`rtt min/avg/max/mdev = [\d\.]+/([\d\.]+)/[\d\.]+/[\d\.]+ ms`)
	matches := re.FindStringSubmatch(outputStr)
	if len(matches) < 2 {
		// Try alternative format for some ping implementations
		re = regexp.MustCompile(`round-trip min/avg/max/stddev = [\d\.]+/([\d\.]+)/[\d\.]+/[\d\.]+ ms`)
		matches = re.FindStringSubmatch(outputStr)
		if len(matches) < 2 {
			// Try parsing individual time lines as fallback
			return parseFallback(outputStr, count)
		}
	}

	avg, err := strconv.ParseFloat(matches[1], 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency: %w", err)
	}

	return avg, nil
}

// parseFallback attempts to parse individual ping time lines when the summary
// line format is not recognized.
func parseFallback(output string, count int) (float64, error) {
	re := regexp.MustCompile(`time=([\d\.]+) ms`)
	matches := re.FindAllStringSubmatch(output, -1)
	if len(matches) == 0 {
		return 0, fmt.Errorf("could not find latency information in ping output:\n%s", output)
	}

	var total float64
	for _, match := range matches {
		t, err := strconv.ParseFloat(match[1], 64)
		if err != nil {
			continue
		}
		total += t
	}

	if len(matches) == 0 {
		return 0, fmt.Errorf("no valid latency measurements found")
	}

	return total / float64(len(matches)), nil
}

func main() {
