func parseAverageLatency(output string) (float64, error) {
    // Look for the summary line like: rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms
    re := regexp.MustCompile(`rtt min/avg/max/mdev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`)
