package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
	}

	return parsePingOutput(string(output))
}

// parsePingOutput extracts the average latency from the ping command output.
func parsePingOutput(output string) (float64, error) {
	lines := strings.Split(strings.TrimSpace(output), "\n")
	if len(lines) == 0 {
		return 0, fmt.Errorf("empty ping output")
	}

	// Try to match the summary line with average/rtt stats
	// Common formats:
	// Linux: rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms
	// macOS: round-trip min/avg/max/stddev = 1.234/2.345/3.456/0.123 ms
	re := regexp.MustCompile(`(?:rtt|round-trip)\s+\S+\s*=\s*[\d.]+/([\d.]+)/[\d.]+/\S+\s*ms`)
	matches := re.FindStringSubmatch(output)
	if len(matches) >= 2 {
		avg, err := strconv.ParseFloat(matches[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %v", err)
		}
		return avg, nil
	}

	return 0, fmt.Errorf("could not find average latency in ping output")
}

func main() {
	// Example usage
	avg, err := MeasureLatency("google.com", 4)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Average latency: %.2f ms\n", avg)
}

