package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Execute the ping command
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
	}

	// Parse the output to extract round-trip times
	outputStr := string(output)
	avg, err := parsePingOutput(outputStr)
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %v", err)
	}

	return avg, nil
}

// parsePingOutput extracts the average latency from ping command output.
// It handles both Linux/macOS and Windows ping output formats.
func parsePingOutput(output string) (float64, error) {
	// Try Linux/macOS format: rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms
	linuxRegex := regexp.MustCompile(`rtt min/avg/max/mdev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`)
	matches := linuxRegex.FindStringSubmatch(output)
	if len(matches) >= 2 {
		return strconv.ParseFloat(matches[1], 64)
	}

	// Try Windows format: Minimum = 1ms, Maximum = 3ms, Average = 2ms
	windowsRegex := regexp.MustCompile(`Average\s*=\s*(\d+)ms`)
	matches = windowsRegex.FindStringSubmatch(output)
	if len(matches) >= 2 {
		return strconv.ParseFloat(matches[1], 64)
	}

	// Try alternative format: round-trip min/avg/max/stddev = 1.234/2.345/3.456/0.123 ms
	altRegex := regexp.MustCompile(`round-trip min/avg/max/stddev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`)
	matches = altRegex.FindStringSubmatch(output)
	if len(matches) >= 2 {
		return strconv.ParseFloat(matches[1], 64)
	}

	return 0, fmt.Errorf("could not parse average latency from output: %s", strings.TrimSpace(output))
}

func main() {
	// Example usage
	avg, err := MeasureLatency("google.com", 4)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Average latency: %.2f ms\n", avg)
}

