}

// parseAverageLatency extracts the average round-trip time from ping output.
// It supports both Linux/macOS and Windows ping output formats.
func parseAverageLatency(output string) (float64, error) {
	lines := strings.Split(strings.TrimSpace(output), "\n")

	// Try Linux/macOS format: rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms
	linuxPattern := regexp.MustCompile(`rtt min/avg/max/mdev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`)
