			if err != nil {
				return 0, fmt.Errorf("failed to parse average latency: %w", err)
			}
			return avg, nil
		}
	}

	// Try Windows format: Minimum = 1ms, Maximum = 2ms, Average = 1ms
	windowsPattern := regexp.MustCompile(`Average\s*=\s*(\d+)ms`)
	for _, line := range lines {
		matches := windowsPattern.FindStringSubmatch(line)
		if len(matches) >= 2 {
			avg, err := strconv.ParseFloat(matches[1], 64)
			if err != nil {
				return 0, fmt.Errorf("failed to parse average latency: %w", err)
			}
			return avg, nil
		}
	}

	return 0, fmt.Errorf("could not parse average latency from ping output:\n%s", output)
}

