package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Execute the ping command with the specified count.
	// -c specifies the number of ping packets to send.
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
	}

	outputStr := string(output)

	// Try to parse the average latency from the ping output.
	// Typical ping output ends with a line like:
	// rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms
	// We'll use a regex to extract the avg value.
	re := regexp.MustCompile(`rtt min/avg/max/mdev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`)
	matches := re.FindStringSubmatch(outputStr)
	if len(matches) >= 2 {
		avg, err := strconv.ParseFloat(matches[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %v", err)
		}
		return avg, nil
	}

	// Alternative pattern for some ping implementations (e.g., Windows-style output
	// or different locales). For Linux/macOS, the above should work.
	// If we cannot find the pattern, try to extract from individual time lines.
	timeRe := regexp.MustCompile(`time=([\d.]+) ms`)
	timeMatches := timeRe.FindAllStringSubmatch(outputStr, -1)
	if len(timeMatches) == 0 {
		return 0, fmt.Errorf("could not parse latency from ping output: %s", outputStr)
	}

	var total float64
	for _, match := range timeMatches {
		t, err := strconv.ParseFloat(match[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse time value: %v", err)
		}
		total += t
	}

	return total / float64(len(timeMatches)), nil
}

func main() {
	// Example usage
	host := "google.com"
	count := 4

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avg)
}

