package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns
// the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Execute the ping command
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w\nOutput: %s", err, string(output))
	}

	// Parse the output to extract round-trip times
	outputStr := string(output)
	latencies, err := parseLatencies(outputStr)
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %w", err)
	}

	if len(latencies) == 0 {
		return 0, fmt.Errorf("no latency data found in ping output")
	}

	// Calculate average latency
	var sum float64
	for _, lat := range latencies {
		sum += lat
	}
	return sum / float64(len(latencies)), nil
}

// parseLatencies extracts individual latency values from ping output.
func parseLatencies(output string) ([]float64, error) {
	var latencies []float64

	// Pattern to match "time=X.XX ms" in ping output lines
	re := regexp.MustCompile(`time=(\d+\.?\d*)\s*ms`)
	matches := re.FindAllStringSubmatch(output, -1)

	for _, match := range matches {
		if len(match) >= 2 {
			lat, err := strconv.ParseFloat(match[1], 64)
			if err != nil {
				continue
			}
			latencies = append(latencies, lat)
		}
	}

	// Fallback: try to parse summary line if individual times not found
	if len(latencies) == 0 {
		// Pattern for summary line like "rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms"
		reSummary := regexp.MustCompile(`=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
		summaryMatches := reSummary.FindStringSubmatch(output)
		if len(summaryMatches) >= 2 {
			avg, err := strconv.ParseFloat(summaryMatches[1], 64)
			if err != nil {
				return nil, fmt.Errorf("failed to parse average from summary: %w", err)
			}
			latencies = append(latencies, avg)
		}
	}

	if len(latencies) == 0 {
		return nil, fmt.Errorf("could not find latency values in output")
	}

	return latencies, nil
}

func main() {
	// Example usage
	host := "google.com"
	count := 4

	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avgLatency)
}

