package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Execute the ping command
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
	}

	// Parse the output to extract latency values
	outputStr := string(output)
	latencies, err := parseLatencies(outputStr)
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %v", err)
	}

	if len(latencies) == 0 {
		return 0, fmt.Errorf("no latency values found in ping output")
	}

	// Calculate average latency
	var sum float64
	for _, lat := range latencies {
		sum += lat
	}
	return sum / float64(len(latencies)), nil
}

// parseLatencies extracts latency values from ping command output.
// It supports both Linux/macOS ping output format.
func parseLatencies(output string) ([]float64, error) {
	var latencies []float64

	// Regex to match time=XX.XXX ms pattern
	re := regexp.MustCompile(`time=(\d+\.?\d*)\s*ms`)
	matches := re.FindAllStringSubmatch(output, -1)

	for _, match := range matches {
		if len(match) >= 2 {
			lat, err := strconv.ParseFloat(match[1], 64)
			if err != nil {
				continue
			}
			latencies = append(latencies, lat)
		}
	}

	// If no matches found, try alternative format (e.g., min/avg/max/mdev)
	if len(latencies) == 0 {
		// Try to parse summary line: rtt min/avg/max/mdev = 1.234/2.345/3.456/0.789 ms
		summaryRe := regexp.MustCompile(`=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
		summaryMatches := summaryRe.FindStringSubmatch(output)
		if len(summaryMatches) >= 2 {
			avg, err := strconv.ParseFloat(summaryMatches[1], 64)
			if err != nil {
				return nil, fmt.Errorf("failed to parse average from summary: %v", err)
			}
			latencies = append(latencies, avg)
		}
	}

	return latencies, nil
}

func main() {
	// Example usage
	host := "google.com"
	count := 4

	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avgLatency)
}

