package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Execute the ping command
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(output))
	}

	// Parse the output to extract average latency
	outputStr := string(output)
	avg, err := parseAverageLatency(outputStr)
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %v", err)
	}

	return avg, nil
}

// parseAverageLatency extracts the average round-trip time from ping output.
func parseAverageLatency(output string) (float64, error) {
	lines := strings.Split(strings.TrimSpace(output), "\n")
	if len(lines) == 0 {
		return 0, fmt.Errorf("empty ping output")
	}

	// Look for the summary line containing "avg" or "average"
	// Example Linux/macOS output: rtt min/avg/max/mdev = 0.123/0.456/0.789/0.123 ms
	// Example Windows output: Minimum = 0ms, Maximum = 1ms, Average = 0ms
	avgRegex := regexp.MustCompile(`(?:avg|Average)\s*=\s*([\d.]+)`)
	slashRegex := regexp.MustCompile(`rtt\s+\S+\s*=\s*[\d.]+/([\d.]+)/`)

	// Try Linux/macOS format first
	for _, line := range lines {
		matches := slashRegex.FindStringSubmatch(line)
		if len(matches) >= 2 {
			avg, err := strconv.ParseFloat(matches[1], 64)
			if err != nil {
				return 0, fmt.Errorf("failed to parse average latency: %v", err)
			}
			return avg, nil
		}
	}

	// Try Windows format
	for _, line := range lines {
		matches := avgRegex.FindStringSubmatch(line)
		if len(matches) >= 2 {
			avg, err := strconv.ParseFloat(matches[1], 64)
			if err != nil {
				return 0, fmt.Errorf("failed to parse average latency: %v", err)
			}
			return avg, nil
		}
	}

	return 0, fmt.Errorf("could not find average latency in ping output")
}

func main() {
	// Example usage
	avg, err := MeasureLatency("google.com", 4)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Average latency: %.2f ms\n", avg)
}

